"""Visual explanation and a self-contained, offline browser dashboard."""


class DesertSubstrateAnalysis:
    """Translate measured learning behavior into a concise, factual readout."""

    def __init__(self):
        self.system_status = "MEASURED_ANALYSIS"

    def describe(self, metrics, count):
        gap = metrics["train_accuracy"] - metrics["test_accuracy"]
        if gap > 0.12:
            return "The training score is ahead of the test score. More varied examples may help."
        if metrics["test_accuracy"] >= 0.95:
            return "The network separates most held-out examples correctly. Try adding a new point."
        return f"Learning from {count} labeled examples. The test set stays separate from training."

    def map_interconnected_truth(self):
        return {"input": "Two normalized coordinates", "hidden_layers": "12 and 8 tanh neurons",
                "output": "Probability of class 1", "learning": "Backpropagation with Adam",
                "evaluation": "Loss and accuracy on held-out labeled examples"}


